const qs = [
  "RunOnce|func .*RunOnce|attachment.*(refresh|stale)|Refresh",
  "webhook|Webhook|SSRF|private|internal network|url.*valid",
  "oauth|OIDC|idp|identity provider",
  "mysql.New|mysql.Open|NewMySQL|mysql.Driver",
  "reaction.*delete|Delete.*reaction|ON DELETE",
  "markdown|Markdown",
  "visibility|Visibility|CanView|memo.*view",
  "Redis|redis|rate.limit|rateLimit|throttle|cron|cleanup|NATS|Rabbit|GraphQL|graphql"
];
const rs = await Promise.all(qs.map(q => tools.exec_command({cmd:`rg -n -i '${q}' --glob '*.go' --glob '*.proto' --glob '*.yaml' --glob '*.yml' --glob '*.ts' --glob '*.tsx' . | head -120`,workdir:"/bench/repo",yield_time_ms:10000,max_output_tokens:7000})));
rs.forEach((r,i)=>{text(`QUERY ${i+1}\n${r.output}`)});

