const cmds=[
"nl -ba server/router/api/v1/memo_service_webhooks.go",
"nl -ba internal/idp/idp.go; nl -ba internal/idp/oauth2/oauth2.go | sed -n '1,40p'; rg -n 'internal/idp|oauth2.New|NewProvider|New.*IDP' --glob '*.go'",
"nl -ba store/driver.go; nl -ba store/db/mysql/mysql.go | sed -n '1,120p'; rg -n 'mysql|postgres|sqlite|NewDB|Open' store --glob '*.go' | head -150",
"nl -ba store/db/mysql/user_delete.go | sed -n '1,180p'; nl -ba store/db/postgres/user_delete.go | sed -n '1,180p'; nl -ba store/db/sqlite/user_delete.go | sed -n '1,180p'",
"nl -ba server/router/fileserver/fileserver.go | sed -n '110,215p'; nl -ba server/router/fileserver/fileserver.go | sed -n '700,730p'; nl -ba store/user.go | sed -n '1,80p'",
"rg -n 'func \\(.*\\) RunOnce|func \\(.*\\) Close' --glob '*.go' server internal store; rg -n '\\.RunOnce\\(|\\.Close\\(' --glob '*.go' server internal store | grep -v _test.go",
"rg -n 'type Service|func New|markdown.Service|MarkdownService' internal/markdown server/router/api/v1 --glob '*.go'; nl -ba internal/markdown/*.go",
"rg -n 'checkMemoReadAccess|VisibilityList|memo.Visibility|canViewerAccessMemo|memoFilter' server/router/api/v1 --glob '*.go' | grep -v _test.go"
];
const rs=await Promise.all(cmds.map(cmd=>tools.exec_command({cmd,workdir:"/bench/repo",yield_time_ms:10000,max_output_tokens:10000})));
rs.forEach((r,i)=>text(`---${i+1}---\n${r.output}`));

const cmds=[
"rg -n 'DeleteReaction|reaction|DELETE FROM reaction|FOREIGN KEY.*reaction|reaction.*ON DELETE' store/db/{mysql,postgres,sqlite} store/migrator.go",
"nl -ba store/db/sqlite/user_delete.go | sed -n '1,180p'; nl -ba store/db/postgres/user_delete.go | sed -n '1,120p'",
"nl -ba store/db/sqlite/memo.go | sed -n '1,55p'; nl -ba store/db/postgres/memo.go | sed -n '1,50p'; nl -ba store/db/mysql/memo.go | sed -n '1,50p'",
"rg -n 'NewService\\(|MarkdownService:|MarkdownService ' --glob '*.go' server internal | grep -v _test.go",
"nl -ba internal/markdown/service.go 2>/dev/null || true; rg --files internal/markdown",
"nl -ba server/router/api/v1/memo_service.go | sed -n '30,75p;178,235p;335,375p'; nl -ba server/router/api/v1/memo_service_comments.go | sed -n '140,185p'; nl -ba server/router/api/v1/attachment_service.go | sed -n '420,465p'; nl -ba server/router/api/v1/memo_attachment_service.go | sed -n '200,230p'",
"nl -ba store/store.go | sed -n '1,110p'; nl -ba store/db/db.go 2>/dev/null || true; rg -n 'NewDBDriver' store"
];
const rs=await Promise.all(cmds.map(cmd=>tools.exec_command({cmd,workdir:"/bench/repo",yield_time_ms:10000,max_output_tokens:8000})));
rs.forEach((r,i)=>text(`---${i+1}---\n${r.output}`));

